mapper.select:
SELECT IF(COUNT(DISTINCT emergency_dept_name) = 4 AND
          SUM(IF(emergency_dept_name NOT IN ('指挥官', '中心组', '计划组', '行动组'), 1, 0)) = 0 AND
          SUM(IF(dept_level != 1, 1, 0)) = 0, 'Yes', 'No') AS is_valid
FROM vm_emergency_dept
WHERE event_code = #{eventCode}
  and delete_flag = 0;

mapper.delete:
update vm_emergency_dept
set delete_flag = 1,
modifier = #{modifier},
update_time = now()
where
tenant_id = #{tenantId}
and industry_code = #{industryCode}
and id = #{id}

mapper.select:
select id, emergency_dept_name, commander_flag
from vm_emergency_dept
where delete_flag = 0
  and tenant_id = #{tenantId}
  and industry_code = #{industryCode}

    and commander_flag != 1


    and event_code = #{eventCode}


    and parent_id = #{parentId}


    and dept_level = #{deptLevel}


    and emergency_dept_name = #{emergencyDeptName}

order by  commander_flag DESC,create_time desc

WITH RECURSIVE category_descendants AS ( SELECT id as messageId, emergency_dept_name as emessageName, parent_id as emessageParentId , 1 as informationFlag ,create_time,ancestors,dept_level FROM vm_emergency_dept WHERE delete_flag = 0
and tenant_id = #{tenantId}
and id in
#{pid}
and id = #{id}
and dept_level = 1
and event_code = #{eventCode} and commander_flag != 1 UNION ALL SELECT c.id as messageId, c.emergency_dept_name as emessageName, c.parent_id as emessageParentId , 1 as informationFlag ,c.create_time,c.ancestors,c.dept_level FROM vm_emergency_dept c INNER JOIN category_descendants cd ON c.parent_id = cd.messageId and c.delete_flag = 0 ) SELECT * FROM category_descendants order by create_time
